@PrefixGameTestTemplate(false)
public final class PlaceholderGameTests{
    private static ServerPlayer player(GameTestHelper h){var p=net.neoforged.neoforge.common.util.FakePlayerFactory.get(h.getLevel(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"MaterialTester"));p.setGameMode(GameType.SURVIVAL);p.getInventory().clearContent();p.setPos(h.absolutePos(new BlockPos(2,2,2)).getCenter());return p;}
    private static ItemStack mana(ServerPlayer p,long amount){var item=ModContent.MANA_CONTAINERS.get("mana_container_expanded").get();var s=new ItemStack(item);item.receive(s,amount,false);p.getInventory().setItem(0,s);return s;}
    @GameTest(template="empty",batch="materials") public static void realMaterialsArePreferredAndOnlyGenerationPaysTheExtraFee(GameTestHelper h){var p=player(h);var battery=mana(p,10000);var storage=(ManaStorage)battery.getItem();p.getInventory().setItem(1,new ItemStack(Items.STONE));p.getInventory().setItem(2,PlaceholderItem.create(ResourceLocation.withDefaultNamespace("stone")));var pos=h.absolutePos(new BlockPos(1,2,1));
        h.assertTrue(MaterialPlacement.place(p,pos,Blocks.STONE.defaultBlockState(),1,false,200,false),"A real stone can be placed");h.assertTrue(p.getInventory().getItem(1).isEmpty()&&storage.stored(battery)==9800,"Real placement consumes one stone and only ordinary operation mana");
        h.assertTrue(MaterialPlacement.place(p,pos.above(),Blocks.STONE.defaultBlockState(),1,false,200,false),"A carried placeholder supplies missing stone");h.assertTrue(storage.stored(battery)==9120&&!p.getInventory().getItem(2).isEmpty(),"Generation adds exactly 480, without consuming the placeholder");h.succeed();}
    @GameTest(template="empty",batch="materials") public static void insufficientGenerationManaCannotPlaceOrConsume(GameTestHelper h){var p=player(h);var s=mana(p,699);p.getInventory().setItem(1,PlaceholderItem.create(ResourceLocation.withDefaultNamespace("water")));var pos=h.absolutePos(new BlockPos(1,2,1));h.assertTrue(!MaterialPlacement.place(p,pos,Blocks.WATER.defaultBlockState(),1,false,200,true)&&h.getLevel().getBlockState(pos).isAir()&&((ManaStorage)s.getItem()).stored(s)==699,"A 700-aether operation must leave world and resources untouched with only 699");h.succeed();}
    @GameTest(template="empty",batch="materials") public static void aBucketIsReturnedAndMissingMaterialsAreNotGeneratedForFree(GameTestHelper h){var p=player(h);var b=mana(p,1000);var pos=h.absolutePos(new BlockPos(1,2,1));h.assertTrue(!MaterialPlacement.place(p,pos,Blocks.WATER.defaultBlockState(),1,false,200,false),"No water bucket and no placeholder means no water");p.getInventory().setItem(1,new ItemStack(Items.WATER_BUCKET));h.assertTrue(MaterialPlacement.place(p,pos,Blocks.WATER.defaultBlockState(),1,false,200,false),"Water is supplied from a real bucket");h.assertTrue(p.getInventory().items.stream().anyMatch(s->s.is(Items.BUCKET))&&((ManaStorage)b.getItem()).stored(b)==800,"The empty bucket returns; no generation fee is charged");h.succeed();}
    @GameTest(template="empty",batch="materials") public static void multipleSnowLayersCannotBeCreatedForOneLayersCost(GameTestHelper h){var p=player(h);var b=mana(p,10000);p.getInventory().setItem(1,PlaceholderItem.create(ResourceLocation.withDefaultNamespace("snow")));var pos=h.absolutePos(new BlockPos(1,2,1));h.getLevel().setBlockAndUpdate(pos.below(),Blocks.STONE.defaultBlockState());h.assertTrue(MaterialPlacement.place(p,pos,Blocks.SNOW.defaultBlockState().setValue(SnowLayerBlock.LAYERS,8),1,false,200,false),"Eight snow layers can be generated");h.assertTrue(((ManaStorage)b.getItem()).stored(b)==6600,"All eight layers must pay generation, preventing a positive snow recycling loop");h.succeed();}
    @GameTest(template="empty",batch="materials") public static void unorderedPlaceholderRecipeEmbedsRealIngredientsAndTheirBuckets(GameTestHelper h){var p=player(h);ResearchKnowledge.learn(p,"K31");var blank=PlaceholderContent.ITEM.toStack();var menu=new PlaceholderMenu(5,p.getInventory(),blank);menu.inputs.setItem(8,cn.nulladev.modularmagic.crafting.ArtificeContent.PLATES.get("K03").toStack());menu.inputs.setItem(3,new ItemStack(Items.WATER_BUCKET));menu.inputs.setItem(5,new ItemStack(Items.WATER_BUCKET));menu.inputs.setItem(1,cn.nulladev.modularmagic.crafting.ArtificeContent.PLATES.get("K07").toStack());var sample=new ItemStack(Items.WATER_BUCKET);menu.setCarried(sample);menu.clicked(9,0,ClickType.PICKUP,p);h.assertTrue(menu.getCarried().is(Items.WATER_BUCKET)&&menu.getCarried().getCount()==1,"The center must not consume its sample");menu.setCarried(ItemStack.EMPTY);h.assertTrue(!menu.result.isEmpty(),"Unordered ring must produce a valid imprint");menu.clicked(10,0,ClickType.PICKUP,p);h.assertTrue(ResourceLocation.withDefaultNamespace("water").equals(PlaceholderItem.target(menu.getCarried())),"The result stores the correct target");h.assertTrue(menu.inputs.getItem(0).isEmpty()&&menu.inputs.getItem(1).isEmpty()&&menu.inputs.getItem(8).isEmpty()&&menu.inputs.getItem(3).isEmpty()&&menu.inputs.getItem(5).isEmpty(),"The blank, nodes and both full water buckets become part of the water sample");h.assertTrue(menu.result.isEmpty(),"Taking the result cannot duplicate the recipe");h.succeed();}
    @GameTest(template="empty",batch="materials") public static void generatorAssemblyUsesRealSpellNodesAndStorageIsInTheHousing(GameTestHelper h){
        for(String id:GeneratorCatalog.RULES.keySet()){
            var recipe=h.getLevel().getRecipeManager().byKey(cn.nulladev.modularmagic.ModularMagic.id("generator_"+id)).orElseThrow().value();
            var list=recipe.getIngredients().stream().map(i->i.getItems()[0].copy()).toList();
            h.assertTrue(list.stream().noneMatch(s->s.getItem() instanceof cn.nulladev.modularmagic.item.NodeItem),"Devices use clay rune plates, not spell gems");
            var input=CraftingInput.of(list.size(),1,list);var crafting=(net.minecraft.world.item.crafting.CraftingRecipe)recipe;
            h.assertTrue(crafting.matches(input,h.getLevel())&&id.equals(GeneratorItem.ruleId(crafting.assemble(input,h.getLevel().registryAccess()))),"The standard JEI-visible recipe must assemble "+id);
        }
        var housing=new GeneratorHousingRecipe(CraftingBookCategory.MISC);var battery=ModContent.MANA_CONTAINERS.get("mana_container_basic").toStack();var parts=CraftingInput.of(5,1,List.of(new ItemStack(Items.COPPER_INGOT),new ItemStack(Items.COPPER_INGOT),new ItemStack(Items.COPPER_INGOT),new ItemStack(Items.QUARTZ),battery));h.assertTrue(housing.matches(parts,h.getLevel()),"A housing incorporates a real empty storage item");((ManaStorage)battery.getItem()).receive(battery,1,false);h.assertTrue(!housing.matches(parts,h.getLevel()),"A charged container must not vanish into a housing");h.succeed();}

    @GameTest(template="empty",batch="materials") public static void allGravityMaterialsShareOneReversibleRule(GameTestHelper h){
        var bind=(CraftingRecipe)h.getLevel().getRecipeManager().byKey(ModularMagic.id("mimic_gravity_bind")).orElseThrow().value();var separate=(CraftingRecipe)h.getLevel().getRecipeManager().byKey(ModularMagic.id("mimic_gravity_separate")).orElseThrow().value();int count=0;
        for(var block:net.minecraft.core.registries.BuiltInRegistries.BLOCK)if(PlaceholderContent.gravity(block)&&!block.asItem().equals(Items.AIR)){
            var material=new ItemStack(block.asItem());for(boolean reverse:List.of(false,true)){var input=CraftingInput.of(2,1,reverse?List.of(material,PlaceholderContent.GRAVITY.toStack()):List.of(PlaceholderContent.GRAVITY.toStack(),material));h.assertTrue(bind.matches(input,h.getLevel()),"Falling material must bind in either order: "+block);var bound=bind.assemble(input,h.getLevel().registryAccess());var one=CraftingInput.of(1,1,List.of(bound));h.assertTrue(separate.matches(one,h.getLevel())&&separate.assemble(one,h.getLevel().registryAccess()).is(PlaceholderContent.GRAVITY.get())&&separate.getRemainingItems(one).getFirst().is(block.asItem()),"Separating must return the common rule AND the original block: "+block);h.assertTrue(Double.isFinite(MaterialPlacement.fee(block.defaultBlockState())),"Every bound gravity material needs a configurable generation fee");}count++;
        }
        h.assertTrue(count>=22,"The family includes verified falling materials and iron anvils");h.assertTrue(!separate.matches(CraftingInput.of(1,1,List.of(PlaceholderContent.ITEM.toStack())),h.getLevel())&&!separate.matches(CraftingInput.of(1,1,List.of(PlaceholderItem.create(ResourceLocation.withDefaultNamespace("water")))),h.getLevel()),"An empty or unrelated mimic cannot become a free gravity rule");h.succeed();
    }
    @GameTest(template="empty",batch="materials") public static void gravitySeparationReturnsItsBlockThroughTheActualCraftingMenu(GameTestHelper h){
        var p=player(h);for(int i=0;i<36;i++)p.getInventory().setItem(i,new ItemStack(Items.COBBLESTONE,64));var pos=h.absolutePos(new BlockPos(1,1,1));h.getLevel().setBlockAndUpdate(pos,Blocks.CRAFTING_TABLE.defaultBlockState());var menu=new net.minecraft.world.inventory.CraftingMenu(43,p.getInventory(),net.minecraft.world.inventory.ContainerLevelAccess.create(h.getLevel(),pos));menu.getSlot(1).set(PlaceholderItem.bind(MimicFamily.GRAVITY,new ItemStack(Items.RED_SAND)));
        menu.clicked(0,0,ClickType.QUICK_MOVE,p);h.assertTrue(MimicBindingRecipe.bound(menu.getSlot(1).getItem()),"Shift-crafting into a full pack must leave the bound mimic intact");menu.clicked(0,0,ClickType.PICKUP,p);h.assertTrue(menu.getCarried().is(PlaceholderContent.GRAVITY.get())&&menu.getSlot(1).getItem().is(Items.RED_SAND)&&menu.getSlot(1).getItem().getCount()==1&&menu.getSlot(0).getItem().isEmpty(),"Taking the common rule returns exactly one original block to the crafting grid");h.succeed();
    }

    @GameTest(template="empty",batch="materials") public static void groupedMimicsRoundTripEveryRecognizedItem(GameTestHelper h){
        for(var family:MimicFamily.values()){
            var bind=(CraftingRecipe)h.getLevel().getRecipeManager().byKey(ModularMagic.id("mimic_"+family.id+"_bind")).orElseThrow().value();var separate=(CraftingRecipe)h.getLevel().getRecipeManager().byKey(ModularMagic.id("mimic_"+family.id+"_separate")).orElseThrow().value();int count=0;
            for(var item:net.minecraft.core.registries.BuiltInRegistries.ITEM){var material=new ItemStack(item);if(!MimicBindingRecipe.sample(family,material))continue;count++;
                var input=CraftingInput.of(2,1,List.of(material,family.template()));h.assertTrue(bind.matches(input,h.getLevel()),"Cannot bind "+family+" "+item);var bound=bind.assemble(input,h.getLevel().registryAccess());var single=CraftingInput.of(1,1,List.of(bound));h.assertTrue(separate.matches(single,h.getLevel())&&separate.assemble(single,h.getLevel().registryAccess()).is(family.template().getItem())&&separate.getRemainingItems(single).getFirst().is(item),"Binding loses or duplicates "+item);h.assertTrue(PlaceholderItem.price(bound)>=0,"Missing configurable cost for "+item);
            }
            h.assertTrue(count>0,"Empty family "+family);
        }
        for(var b:List.of(Blocks.MELON,Blocks.PUMPKIN,Blocks.SUGAR_CANE,Blocks.CACTUS,Blocks.KELP,Blocks.OAK_LOG,Blocks.OAK_LEAVES,Blocks.BROWN_MUSHROOM,Blocks.RED_MUSHROOM))h.assertTrue(MimicFamily.PLANTS.matches(b),"Missing plant "+b);
        for(var b:List.of(Blocks.RED_MUSHROOM_BLOCK,Blocks.BROWN_MUSHROOM_BLOCK,Blocks.MUSHROOM_STEM))h.assertTrue(!MimicFamily.PLANTS.matches(b),"Huge mushroom blocks must not use natural mushroom spreading");h.succeed();
    }
    @GameTest(template="empty",batch="materials") public static void advancedPlantSampleRetainsItsFertilizerAndAddsItsPrice(GameTestHelper h){
        var level=h.getLevel();
        var bone=PlaceholderItem.derived(new ItemStack(Items.BONE_MEAL),736);
        var upgrade=(CraftingRecipe)level.getRecipeManager().byKey(ModularMagic.id("plant_template_upgrade")).orElseThrow().value();
        var input=CraftingInput.of(2,1,List.of(bone,PlaceholderContent.PLANTS.toStack()));
        h.assertTrue(upgrade.matches(input,level),"The upgrade is shapeless");
        var advanced=upgrade.assemble(input,level.registryAccess());
        var flower=new ItemStack(Items.SUNFLOWER);
        var plant=(CraftingRecipe)level.getRecipeManager().byKey(ModularMagic.id("mimic_plants_bind")).orElseThrow().value();
        var advancedPlant=(CraftingRecipe)level.getRecipeManager().byKey(ModularMagic.id("mimic_advanced_plants_bind")).orElseThrow().value();
        var planting=CraftingInput.of(2,1,List.of(advanced,flower));
        h.assertTrue(!plant.matches(CraftingInput.of(2,1,List.of(PlaceholderContent.PLANTS.toStack(),flower)),level)
                &&advancedPlant.matches(planting,level),"Bonemeal-dependent plants fit the upgraded template only");
        var bound=advancedPlant.assemble(planting,level.registryAccess());
        h.assertTrue(PlaceholderItem.price(bound)==MaterialPlacement.fee(Blocks.SUNFLOWER.defaultBlockState())+736,"Every generated plant includes its installed bone meal price");
        var unbind=(CraftingRecipe)level.getRecipeManager().byKey(ModularMagic.id("mimic_advanced_plants_separate")).orElseThrow().value();
        var boundInput=CraftingInput.of(1,1,List.of(bound));
        var empty=unbind.assemble(boundInput,level.registryAccess());
        var split=(CraftingRecipe)level.getRecipeManager().byKey(ModularMagic.id("plant_template_separate")).orElseThrow().value();
        var emptyInput=CraftingInput.of(1,1,List.of(empty));
        h.assertTrue(split.matches(emptyInput,level)&&split.assemble(emptyInput,level.registryAccess()).is(PlaceholderContent.PLANTS.get())
                &&ItemStack.isSameItemSameComponents(split.getRemainingItems(emptyInput).getFirst(),bone),"Separation returns the original bone meal sample in its grid slot");
        h.succeed();
    }
    @GameTest(template="empty",batch="materials") public static void stonesAndIceNeedTwoBucketsAndObsidianHasThreeRoutes(GameTestHelper h){
        for(String id:List.of("stone","ice")){var recipe=h.getLevel().getRecipeManager().byKey(ModularMagic.id("placeholder_"+id)).orElseThrow().value();h.assertTrue(recipe instanceof PlaceholderRecipe,"Wrong recipe type");var r=(PlaceholderRecipe)recipe;h.assertTrue(r.ingredients().stream().filter(i->i.test(new ItemStack(Items.WATER_BUCKET))).count()==2,"Spent water needs two sources in "+id);var list=r.ingredients().stream().map(i->i.getItems()[0].copy()).toList();h.assertTrue(r.matches(CraftingInput.of(list.size(),1,new ArrayList<>(list)),h.getLevel()),"The complete ring must match");var missing=new ArrayList<>(list);missing.remove(missing.stream().filter(st->st.is(Items.WATER_BUCKET)).findFirst().orElseThrow());h.assertTrue(!r.matches(CraftingInput.of(missing.size(),1,missing),h.getLevel()),"One water bucket must not substitute for an inexhaustible supply");}
        long routes=h.getLevel().getRecipeManager().getAllRecipesFor(PlaceholderContent.TYPE.get()).stream().filter(r->r.value().target().equals(ResourceLocation.withDefaultNamespace("obsidian"))).count();h.assertTrue(routes==3,"Obsidian needs lava, platform and pillar recipes");h.succeed();
    }
    @GameTest(template="empty",batch="materials") public static void railAndCarpetCostsAreUniformAndNewMaterialsArePriced(GameTestHelper h){
        double rail=MaterialPlacement.fee(Blocks.RAIL.defaultBlockState());for(var b:List.of(Blocks.RAIL,Blocks.POWERED_RAIL,Blocks.DETECTOR_RAIL,Blocks.ACTIVATOR_RAIL))h.assertTrue(MaterialPlacement.fee(b.defaultBlockState())==rail,"All rail variants must have one fee");h.assertTrue(rail>0&&rail<=32,"Rail generation should be cheap");h.assertTrue(MaterialPlacement.fee(Blocks.WHITE_CARPET.defaultBlockState())==MaterialPlacement.fee(Blocks.BLACK_CARPET.defaultBlockState()),"Carpet color must not change its cost");
        for(var b:List.of(Blocks.POWDER_SNOW,Blocks.OBSIDIAN,Blocks.AMETHYST_CLUSTER,Blocks.POINTED_DRIPSTONE,Blocks.SCULK))h.assertTrue(Double.isFinite(MaterialPlacement.fee(b.defaultBlockState()))&&MaterialPlacement.fee(b.defaultBlockState())>0,"Unpriced material "+b);h.succeed();
    }
    @GameTest(template="empty",batch="materials") public static void mimicsPlaceWallCrystalsHangingDripstoneAndCompletePlants(GameTestHelper h){
        var p=player(h);var place=cn.nulladev.modularmagic.utility.UtilityContent.PLACE.get();var battery=new ItemStack(place);place.receive(battery,50000,false);p.getInventory().selected=1;p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,battery);var base=h.absolutePos(new BlockPos(1,2,1));h.getLevel().setBlockAndUpdate(base,Blocks.STONE.defaultBlockState());
        cn.nulladev.modularmagic.utility.AetherUtilityItem.setSample(battery,PlaceholderItem.create(ResourceLocation.withDefaultNamespace("amethyst_cluster")));var hit=new net.minecraft.world.phys.BlockHitResult(base.getCenter(),Direction.EAST,base,false);place.useOn(new net.minecraft.world.item.context.UseOnContext(p,net.minecraft.world.InteractionHand.MAIN_HAND,hit));h.assertTrue(h.getLevel().getBlockState(base.east()).is(Blocks.AMETHYST_CLUSTER)&&h.getLevel().getBlockState(base.east()).getValue(net.minecraft.world.level.block.state.properties.BlockStateProperties.FACING)==Direction.EAST,"The cluster must attach to the clicked wall");
        p.setXRot(-80);var ceiling=base.above(2);h.getLevel().setBlockAndUpdate(ceiling,Blocks.STONE.defaultBlockState());cn.nulladev.modularmagic.utility.AetherUtilityItem.setSample(battery,PlaceholderItem.create(ResourceLocation.withDefaultNamespace("pointed_dripstone")));hit=new net.minecraft.world.phys.BlockHitResult(ceiling.getCenter(),Direction.DOWN,ceiling,false);place.useOn(new net.minecraft.world.item.context.UseOnContext(p,net.minecraft.world.InteractionHand.MAIN_HAND,hit));h.assertTrue(h.getLevel().getBlockState(ceiling.below()).is(Blocks.POINTED_DRIPSTONE)&&h.getLevel().getBlockState(ceiling.below()).getValue(net.minecraft.world.level.block.state.properties.BlockStateProperties.VERTICAL_DIRECTION)==Direction.DOWN,"The stone must hang from its ceiling");
        var soil=base.south(2);h.getLevel().setBlockAndUpdate(soil,Blocks.DIRT.defaultBlockState());h.getLevel().setBlockAndUpdate(soil.above(),Blocks.AIR.defaultBlockState());h.getLevel().setBlockAndUpdate(soil.above(2),Blocks.AIR.defaultBlockState());cn.nulladev.modularmagic.utility.AetherUtilityItem.setSample(battery,PlaceholderItem.create(ResourceLocation.withDefaultNamespace("sunflower")));hit=new net.minecraft.world.phys.BlockHitResult(soil.getCenter(),Direction.UP,soil,false);place.useOn(new net.minecraft.world.item.context.UseOnContext(p,net.minecraft.world.InteractionHand.MAIN_HAND,hit));h.assertTrue(h.getLevel().getBlockState(soil.above()).is(Blocks.SUNFLOWER)&&h.getLevel().getBlockState(soil.above(2)).is(Blocks.SUNFLOWER),"A double-height plant must include both halves");var bamboo=base.east(2);h.getLevel().setBlockAndUpdate(bamboo,Blocks.DIRT.defaultBlockState());h.getLevel().setBlockAndUpdate(bamboo.above(),Blocks.AIR.defaultBlockState());cn.nulladev.modularmagic.utility.AetherUtilityItem.setSample(battery,PlaceholderItem.create(ResourceLocation.withDefaultNamespace("bamboo")));hit=new net.minecraft.world.phys.BlockHitResult(bamboo.getCenter(),Direction.UP,bamboo,false);place.useOn(new net.minecraft.world.item.context.UseOnContext(p,net.minecraft.world.InteractionHand.MAIN_HAND,hit));h.assertTrue(h.getLevel().getBlockState(bamboo.above()).is(Blocks.BAMBOO_SAPLING)||h.getLevel().getBlockState(bamboo.above()).is(Blocks.BAMBOO),"Bamboo must use its native sapling placement");
        var kelp=base.north();h.getLevel().setBlockAndUpdate(kelp,Blocks.STONE.defaultBlockState());h.getLevel().setBlockAndUpdate(kelp.above(),Blocks.WATER.defaultBlockState());h.getLevel().setBlockAndUpdate(kelp.above(2),Blocks.AIR.defaultBlockState());cn.nulladev.modularmagic.utility.AetherUtilityItem.setSample(battery,PlaceholderItem.create(ResourceLocation.withDefaultNamespace("kelp")));hit=new net.minecraft.world.phys.BlockHitResult(kelp.getCenter(),Direction.UP,kelp,false);place.useOn(new net.minecraft.world.item.context.UseOnContext(p,net.minecraft.world.InteractionHand.MAIN_HAND,hit));h.assertTrue(h.getLevel().getBlockState(kelp.above()).is(Blocks.KELP),"Kelp must plant into water without a forged growth age");h.assertTrue(((ManaStorage)battery.getItem()).stored(battery)==50000-10000-1200-1200-1200-1200,"Placement must pay once per actual plant or crystal");h.succeed();
    }
}
